{
  "name": "Keithley 485 皮安计",
  "name_en": "Keithley 485 Picoammeter",
  "manufacturer": "Keithley",
  "description": "Keithley 485 是一款4位半分辨率、自动量程的皮安计，用于测量极低电流，量程覆盖约 0.1 pA 到 2 mA。它适合实验室中的微弱电流检测，如器件漏电流、传感器输出电流和光电探测电流测量。",
  "description_en": "The Keithley 485 is a 4.5-digit autoranging picoammeter for measuring very low currents, covering roughly 0.1 pA to 2 mA. It is used in laboratories for weak-current measurements such as device leakage current, sensor output current, and photocurrent measurements.",
  "tag_hints": [
    "picoammeter",
    "ultra-low current measurement",
    "autoranging current meter",
    "leakage current testing",
    "photocurrent measurement",
    "electrometer applications"
  ],
  "actions": [
    {
      "action_name": "auto-zero_check",
      "description": "获取/设置零点检查模式。",
      "description_en": "Get/set zero-check mode."
    },
    {
      "action_name": "auto-log",
      "description": "获取/设置对数测量模式。",
      "description_en": "Get/set logarithmic reading mode."
    },
    {
      "action_name": "auto-input_range",
      "description": "获取/设置输入电流量程。",
      "description_en": "Get/set input current range."
    },
    {
      "action_name": "auto-relative",
      "description": "获取/设置相对测量模式。",
      "description_en": "Get/set relative measurement mode."
    },
    {
      "action_name": "auto-eoi_mode",
      "description": "获取/设置 EOI 模式。",
      "description_en": "Get/set EOI signaling mode."
    },
    {
      "action_name": "auto-trigger_mode",
      "description": "获取/设置触发模式。",
      "description_en": "Get/set trigger mode."
    },
    {
      "action_name": "auto-auto_range",
      "description": "启用自动量程。",
      "description_en": "Enable auto range."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取设备状态字。",
      "description_en": "Get the device status word."
    },
    {
      "action_name": "auto-measure",
      "description": "执行一次电流测量。",
      "description_en": "Perform a current measurement."
    }
  ]
}

